function RoleLogin({ onSignIn }) {
  const [role, setRole] = useState('agent')
  const [email, setEmail] = useState('agent@kyvo.test')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const roleConfig = role === 'agent' ? { label: 'Collections Agent', email: 'agent@kyvo.test', description: 'Work your assigned queue and manage borrower follow-ups.' } : { label: 'Supervisor', email: 'supervisor@kyvo.test', description: 'Coordinate team workload, reassignment, and escalations.' }
  const chooseRole = (next) => { setRole(next); setEmail(next === 'agent' ? 'agent@kyvo.test' : 'supervisor@kyvo.test'); setError('') }
  const submit = (event) => { event.preventDefault(); const normalizedEmail = email.trim().toLowerCase(); if (!normalizedEmail || !password) { setError('Enter your work email and the demo password to continue.'); return } setLoading(true); window.setTimeout(() => { if (password.trim() !== 'kyvo123') { setLoading(false); setError('Use the demo password shown below to continue.'); return } onSignIn({ ...demoUsers[roleConfig.email], email: normalizedEmail }) }, 400) }
  return <div className="login-page"><div className="login-aside"><div className="aside-glow" /><div className="login-illustration"><svg viewBox="0 0 620 430" role="img" aria-label="Kyvo collections workspace illustration"><rect className="illustration-window" x="100" y="72" width="420" height="250" rx="18" /><rect className="illustration-topbar" x="100" y="72" width="420" height="42" rx="18" /><rect className="illustration-sidebar" x="122" y="132" width="88" height="164" rx="8" /><rect className="illustration-content" x="231" y="132" width="267" height="164" rx="8" /><path className="illustration-chart" d="M253 263c32-45 50-3 81-46s54 25 82-26 50 6 75-40" /><circle className="illustration-point" cx="491" cy="151" r="6" /></svg></div><div className="login-quote"><span>“</span><p>Every conversation is a step closer to resolution.</p><small>Kyvo Collector workspace</small></div><div className="login-footer">© 2026 Kyvo Technologies</div></div><div className="login-panel"><div className="brand login-brand"><div className="brand-mark">K</div><div><strong>kyvo</strong><span>COLLECTOR</span></div></div><div className="login-copy"><p className="eyebrow">COLLECTIONS WORKSPACE</p><h1>Welcome back.</h1><p>Choose how you’re signing in today.</p></div><div className="role-choice"><button type="button" className={role === 'agent' ? 'active' : ''} onClick={() => chooseRole('agent')}><span className="role-choice-icon">◌</span><span><strong>Collections Agent</strong><small>Assigned cases and borrower conversations</small></span><b>✓</b></button><button type="button" className={role === 'supervisor' ? 'active' : ''} onClick={() => chooseRole('supervisor')}><span className="role-choice-icon">◎</span><span><strong>Supervisor</strong><small>Team workload and case coordination</small></span><b>✓</b></button></div><p className="role-description">{roleConfig.description}</p><form onSubmit={submit} className="login-form"><label>Work email<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} /></label><label>Password<input type="password" placeholder="Enter demo password" value={password} onChange={(e) => setPassword(e.target.value)} /></label>{error && <div className="login-error">{error}</div>}<button className="button button-primary login-submit" disabled={loading}>{loading ? 'Signing in…' : `Continue as ${roleConfig.label}`} {!loading && <span>→</span>}</button></form><div className="demo-hint"><span>Prototype access</span><p>Demo password: <strong>kyvo123</strong></p></div></div></div>
}

function TaskModal({ cases, query, setQuery, customerId, setCustomerId, channel, setChannel, date, setDate, time, setTime, note, setNote, onClose, onSave }) {
  const matches = cases.filter((item) => `${item.name} ${item.phone} ${item.loan}`.toLowerCase().includes(query.toLowerCase()))
  return <div className="modal-backdrop" onClick={onClose}><form className="modal task-modal" onSubmit={onSave} onClick={(e) => e.stopPropagation()}><button type="button" className="modal-close" onClick={onClose}>×</button><p className="eyebrow">TASK PLANNER</p><h2>Schedule a follow-up</h2><p className="modal-subtitle">Create as many future tasks as the case needs.</p><label className="modal-label">Assigned customer<select value={customerId} onChange={(e) => setCustomerId(e.target.value)} required><option value="">Select an assigned customer</option>{matches.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.loan} · {item.phone}</option>)}</select></label><div className="customer-search-row"><input placeholder="Search assigned customers" value={query} onChange={(e) => setQuery(e.target.value)} /><button type="button" className="button button-secondary">Search</button></div><label className="modal-label">Follow-up channel<select value={channel} onChange={(e) => setChannel(e.target.value)}><option>Call</option><option>Email</option><option>SMS</option><option>WhatsApp</option></select></label><div className="task-date-grid"><label className="modal-label">Date<input type="date" value={date} onChange={(e) => setDate(e.target.value)} required /></label><label className="modal-label">Time<input type="time" value={time} onChange={(e) => setTime(e.target.value)} /></label></div><label className="modal-label">Task note <span className="optional">Optional</span><textarea rows="2" placeholder="What should happen next?" value={note} onChange={(e) => setNote(e.target.value)} /></label><div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Cancel</button><button type="submit" className="button button-primary">Schedule task</button></div></form></div>
}

function OutcomeModal({ selected, channel, setChannel, outcome, setOutcome, notes, setNotes, followupChannel, setFollowupChannel, followupDate, setFollowupDate, ptpAmount, setPtpAmount, ptpDate, setPtpDate, error, onClose, onSave }) {
  return <div className="modal-backdrop" onClick={onClose}><form className="modal outcome-modal" onSubmit={onSave} onClick={(e) => e.stopPropagation()}><button type="button" className="modal-close" onClick={onClose}>×</button><p className="eyebrow">COLLECTION ACTIVITY</p><h2>Log outcome</h2><p className="modal-subtitle">{selected.name} · {selected.loan} · {selected.attempts} attempts today</p><fieldset className="outcome-section"><legend>Contact channel</legend><div className="choice-grid">{['Call','Email','SMS','WhatsApp'].map((item) => <button type="button" key={item} className={channel === (item === 'Call' ? 'Phone' : item) ? 'active' : ''} onClick={() => setChannel(item === 'Call' ? 'Phone' : item)}>{item}</button>)}</div></fieldset><label className="modal-label">Outcome<select value={outcome} onChange={(e) => setOutcome(e.target.value)}><option>Answered</option><option>No Answer</option><option>Promise to Pay</option><option>Refused</option><option>Wrong Number</option><option>Callback Requested</option></select></label>{outcome === 'Promise to Pay' && <fieldset className="outcome-section conditional-section"><legend>Promise to Pay details</legend><div className="task-date-grid"><label className="modal-label">Amount promised<input inputMode="numeric" placeholder="₦0" value={ptpAmount} onChange={(e) => setPtpAmount(e.target.value)} required /></label><label className="modal-label">Promised date<input type="date" value={ptpDate} onChange={(e) => setPtpDate(e.target.value)} required /></label></div></fieldset>}<label className="modal-label">Notes <span className="optional">Optional</span><textarea rows="2" placeholder="Add useful context for the next collector" value={notes} onChange={(e) => setNotes(e.target.value)} /></label>{outcome !== 'Answered' && outcome !== 'Wrong Number' && <fieldset className="outcome-section conditional-section"><legend>Schedule follow-up <span>Optional</span></legend><div className="task-date-grid"><label className="modal-label">Channel<select value={followupChannel} onChange={(e) => setFollowupChannel(e.target.value)}><option>Call</option><option>Email</option><option>SMS</option><option>WhatsApp</option></select></label><label className="modal-label">Date<input type="date" value={followupDate} onChange={(e) => setFollowupDate(e.target.value)} /></label></div></fieldset>}{error && <div className="login-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={onClose}>Cancel</button><button type="submit" className="button button-primary">Save outcome</button></div></form></div>
}

